/* ---------- Asie (1/2) : Chine régionale, Japon, Corée ---------- */
const D44 = [
{ id:'shuizhu-yu', c:'as', lat:29.563, lon:106.551, base:4, prep:35, cook:20, diff:2, tags:['sea','spicy','fast'],
  art:{v:'bowl',bg:'#33251c',plate:'#f2e8d0',style:'fish',food:['#c9402c','#e0913a','#f4f0e6','#8f3b2a'],garnish:'#7fae6a'},
  n:{fr:'Poisson bouilli à l’eau du Sichuan',en:'Sichuan water-boiled fish'},
  p:{fr:'Chongqing, Chine',en:'Chongqing, China'},
  d:{fr:"Le nom promet de l'eau bouillante et ne livre qu'un lac d'huile rouge : des lamelles de poisson pochées sous une avalanche de piments séchés et de poivre du Sichuan. La couche d'huile n'est pas une sauce, c'est un couvercle thermique.",
     en:"The name promises boiling water and delivers a lake of red oil: slivers of fish poached under an avalanche of dried chilli and Sichuan pepper. The oil layer is not a sauce, it is a thermal lid."},
  i:[['whitefish',800,'g'],['egg_white',1,'pc'],['potato_starch',2,'tbsp'],['doubanjiang',3,'tbsp'],['dried_chili',30,'g'],['sichuan_peppercorns',2,'tbsp'],['bean_sprouts',300,'g'],['garlic',8,'clove'],['ginger',30,'g'],['scallion',4,'pc'],['chicken_broth',800,'ml'],['peanut_oil',200,'ml'],['rice_wine',3,'tbsp'],['salt',null,'']],
  s:{fr:["Levez les filets et tranchez-les en biais, très fin ; massez-les avec le blanc d'œuf, la fécule et le vin de riz, et laissez 20 minutes.","Faites blanchir les germes de soja une minute et rangez-les au fond d'un grand bol.","Faites revenir le doubanjiang dans un peu d'huile jusqu'à ce qu'elle rougisse, ajoutez l'ail et le gingembre, puis le bouillon.","Pochez les lamelles de poisson une à une, 90 secondes à peine : elles blanchissent et remontent. Versez le tout sur les germes.","Chauffez l'huile restante avec les piments et le poivre du Sichuan jusqu'à ce qu'elle fume, et versez-la brûlante sur le poisson."],
     en:["Fillet the fish and slice it thinly on the bias; massage with the egg white, starch and rice wine, and leave for 20 minutes.","Blanch the bean sprouts for a minute and lay them in the bottom of a large bowl.","Fry the doubanjiang in a little oil until it turns red, add the garlic and ginger, then the broth.","Poach the fish slices one by one for barely 90 seconds: they whiten and rise. Pour everything over the sprouts.","Heat the remaining oil with the dried chillies and Sichuan pepper until smoking, and pour it scalding over the fish."]} },

{ id:'char-siu', c:'as', lat:23.129, lon:113.264, base:6, prep:30, cook:60, diff:2, tags:['pork','grill','street'],
  art:{v:'board',bg:'#33251c',plate:'#f2e6c8',style:'grill',food:['#8f1a3a','#c9402c','#e0913a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Char siu',en:'Char siu'},
  p:{fr:'Canton, Guangdong, Chine',en:'Guangzhou, Guangdong, China'},
  d:{fr:"Le porc laqué cantonais, rouge et brillant, suspendu aux crochets des vitrines. Char siu veut dire « rôti à la fourche » : la viande était enfilée sur de longues broches et cuite au-dessus du feu, jamais posée.",
     en:"Cantonese lacquered pork, red and glossy, hanging on hooks in shop windows. Char siu means 'fork roasted': the meat was threaded on long skewers and cooked over the fire, never laid down."},
  i:[['pork_shoulder',1.2,'kg'],['hoisin_sauce',4,'tbsp'],['soy_sauce',4,'tbsp'],['honey',5,'tbsp'],['rice_wine',3,'tbsp'],['five_spice',2,'tsp'],['garlic',6,'clove'],['red_food_coloring',1,'tsp'],['brown_sugar',3,'tbsp'],['sesame_oil',1,'tbsp'],['long_grain_rice',400,'g'],['bok_choy',400,'g'],['salt',null,'']],
  s:{fr:["Détaillez le porc en longues bandes de 5 cm d'épaisseur : c'est la forme qui permet une caramélisation sur toutes les faces.","Mêlez tous les ingrédients de la marinade sauf la moitié du miel, et faites mariner la viande 24 heures.","Enfournez sur une grille, au-dessus d'un plat d'eau, 30 minutes à 200 °C.","Retournez, badigeonnez de marinade et poursuivez 20 minutes.","Badigeonnez du miel restant et passez 8 minutes sous le gril, en surveillant : la laque doit brunir par plaques sans brûler."],
     en:["Cut the pork into long strips 5 cm thick: that shape allows caramelisation on every side.","Mix all the marinade ingredients except half the honey, and marinate the meat for 24 hours.","Roast on a rack over a tray of water for 30 minutes at 200°C.","Turn, brush with marinade and continue for 20 minutes.","Brush with the remaining honey and grill for 8 minutes, watching closely: the lacquer should brown in patches without burning."]} },

{ id:'dongpo-rou', c:'as', lat:30.259, lon:120.155, base:6, prep:30, cook:180, diff:2, tags:['pork','slow','festive'],
  art:{v:'bowl',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f2a2a','#8f5a2b','#f0e8d0','#c9754a'],garnish:'#7fae6a'},
  n:{fr:'Porc de Dongpo',en:'Dongpo pork'},
  p:{fr:'Hangzhou, Zhejiang, Chine',en:'Hangzhou, Zhejiang, China'},
  d:{fr:"Des cubes de poitrine braisés trois heures au vin de Shaoxing jusqu'à ce que le gras devienne translucide. Su Dongpo, poète et gouverneur du XIe siècle, l'aurait offert aux ouvriers qui draguaient le lac de l'Ouest.",
     en:"Cubes of pork belly braised for three hours in Shaoxing wine until the fat turns translucent. Su Dongpo, an 11th-century poet and governor, is said to have given it to the labourers dredging West Lake."},
  i:[['pork_belly',1.5,'kg'],['rice_wine',500,'ml'],['soy_sauce',150,'ml'],['brown_sugar',80,'g'],['ginger',60,'g'],['scallion',8,'pc'],['star_anise',3,'pc'],['cinnamon',1,'pc'],['long_grain_rice',400,'g'],['bok_choy',400,'g'],['salt',null,'']],
  s:{fr:["Blanchissez la poitrine entière 5 minutes, rincez-la et taillez-la en cubes de 5 cm avec la couenne.","Tapissez le fond d'une cocotte de tiges de ciboule et de rondelles de gingembre : la viande ne doit jamais toucher le métal.","Rangez les cubes couenne vers le haut, serrés, en une seule couche.","Versez le vin de riz, la sauce soja et le sucre, ajoutez badiane et cannelle, et couvrez.","Laissez mijoter 2 h 30 à feu très doux, puis passez chaque cube 20 minutes à la vapeur. La couenne doit trembler."],
     en:["Blanch the whole belly for 5 minutes, rinse it and cut it into 5 cm cubes with the rind.","Line the base of a pot with spring onion stalks and ginger slices: the meat must never touch the metal.","Pack the cubes rind upwards, tightly, in a single layer.","Pour in the rice wine, soy sauce and sugar, add the star anise and cinnamon, and cover.","Simmer for 2½ hours over very low heat, then steam each cube for 20 minutes. The rind should wobble."]} },

{ id:'jianbing', c:'as', lat:36.651, lon:117.120, base:4, prep:25, cook:15, diff:2, tags:['street','breakfast','fast'],
  art:{v:'board',bg:'#33301f',plate:'#f2e6c8',style:'flat',food:['#e8c46a','#f2dfa8','#4f8f4a','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Jianbing',en:'Jianbing'},
  p:{fr:'Jinan, Shandong, Chine',en:'Jinan, Shandong, China'},
  d:{fr:"Une crêpe de céréales étalée à la raclette sur une plaque brûlante, cassée d'un œuf, pliée sur une galette croustillante. Le petit-déjeuner de rue chinois par excellence, servi en quatre-vingt-dix secondes.",
     en:"A grain crêpe spread with a wooden rake on a scorching griddle, cracked with an egg, folded around a crisp cracker. The Chinese street breakfast par excellence, served in ninety seconds."},
  i:[['flour',150,'g'],['buckwheat_flour',100,'g'],['cornmeal',50,'g'],['water',600,'ml'],['egg',8,'pc'],['scallion',6,'pc'],['cilantro',1,'bunch'],['hoisin_sauce',4,'tbsp'],['chili_oil',3,'tbsp'],['sesame_seeds',3,'tbsp'],['wonton_wrapper',8,'pc'],['frying_oil',300,'ml'],['salt',null,'']],
  s:{fr:["Fouettez les trois farines dans l'eau jusqu'à obtenir une pâte très fluide, et laissez reposer 30 minutes.","Faites frire les carrés de pâte à raviolis jusqu'à ce qu'ils gonflent et croustillent ; égouttez-les.","Versez une louche de pâte sur une plaque huilée et étalez-la en cercle très fin d'un geste circulaire.","Cassez un œuf dessus, étalez-le à la spatule, parsemez de sésame, de ciboule et de coriandre, puis retournez la crêpe.","Badigeonnez de sauce hoisin et d'huile pimentée, posez la galette croustillante au centre, pliez en quatre et servez aussitôt."],
     en:["Whisk the three flours into the water to a very thin batter, and rest for 30 minutes.","Fry the wonton squares until they puff and crisp; drain them.","Pour a ladle of batter onto an oiled griddle and spread it into a very thin circle with a circular sweep.","Crack an egg on top, spread it with a spatula, scatter sesame, spring onion and coriander, then flip the crêpe.","Brush with hoisin and chilli oil, lay the crisp cracker in the centre, fold into quarters and serve at once."]} },

{ id:'guilin-mifen', c:'as', lat:25.234, lon:110.180, base:4, prep:30, cook:180, diff:2, tags:['noodles','street','comfort'],
  art:{v:'bowl',bg:'#2b2419',plate:'#f0e4c8',style:'noodle',food:['#f0e8d0','#6f4a2a','#7fae5a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Nouilles de riz au bouillon de Liuzhou',en:'Liuzhou rice noodles'},
  p:{fr:'Liuzhou, Guangxi, Chine',en:'Liuzhou, Guangxi, China'},
  d:{fr:"Des nouilles de riz dans un bouillon aux pousses de bambou fermentées, dont l'odeur puissante précède le bol de plusieurs mètres. Les habitants la jugent irrésistible ; les visiteurs mettent parfois une bouchée à s'y faire.",
     en:"Rice noodles in a broth of fermented bamboo shoots, whose powerful smell reaches you several metres before the bowl. Locals find it irresistible; visitors sometimes need a mouthful to come round."},
  i:[['rice_noodles',400,'g'],['pork_bones',800,'g'],['bamboo_shoots',300,'g'],['dried_fish',60,'g'],['peanuts',80,'g'],['pickled_beans',150,'g'],['bean_sprouts',200,'g'],['chili_oil',3,'tbsp'],['scallion',4,'pc'],['cilantro',1,'bunch'],['star_anise',2,'pc'],['ginger',40,'g'],['salt',null,'']],
  s:{fr:["Blanchissez les os de porc, rincez-les, puis faites-les mijoter 3 heures avec le gingembre, la badiane et les petits poissons séchés.","Filtrez le bouillon : il doit être trouble et profondément parfumé.","Faites revenir les pousses de bambou fermentées deux minutes dans l'huile — c'est ce moment qui libère leur odeur — puis versez-les dans le bouillon.","Faites frire les cacahuètes à l'huile jusqu'à ce qu'elles blondissent, et égouttez-les.","Cuisez les nouilles de riz 3 minutes, dressez-les dans les bols, versez le bouillon brûlant et couvrez de bambou, haricots marinés, cacahuètes, germes et herbes."],
     en:["Blanch the pork bones, rinse them, then simmer for 3 hours with the ginger, star anise and dried fish.","Strain the broth: it should be cloudy and deeply fragrant.","Fry the fermented bamboo shoots for two minutes in oil — this is the moment their smell is released — then tip them into the broth.","Fry the peanuts in oil until golden, and drain them.","Cook the rice noodles for 3 minutes, put them in bowls, pour over the scalding broth and top with bamboo, pickled beans, peanuts, sprouts and herbs."]} },

{ id:'foshan-fotiaoqiang', c:'as', lat:26.075, lon:119.306, base:6, prep:120, cook:300, diff:3, tags:['sea','festive','slow'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'soup',food:['#8f6a4a','#c9a878','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Le Bouddha saute le mur',en:'Buddha jumps over the wall'},
  p:{fr:'Fuzhou, Fujian, Chine',en:'Fuzhou, Fujian, China'},
  d:{fr:"Une soupe de dix-huit ingrédients mijotée dans une jarre scellée au vin de Shaoxing. Le nom vient d'un poème : un moine, sentant le parfum par-dessus le mur du monastère, aurait enjambé la clôture pour y goûter.",
     en:"A soup of eighteen ingredients simmered in a jar sealed with Shaoxing wine. The name comes from a poem: a monk, catching the scent over the monastery wall, is said to have vaulted the fence to taste it."},
  i:[['chicken',800,'g'],['pork_belly',400,'g'],['duck_legs',400,'g'],['shiitake_mushrooms',80,'g'],['bamboo_shoots',200,'g'],['scallops',150,'g'],['dried_shrimp',60,'g'],['ginger',60,'g'],['scallion',6,'pc'],['rice_wine',400,'ml'],['soy_sauce',60,'ml'],['chicken_broth',1.5,'l'],['goji_berries',40,'g'],['salt',null,'']],
  s:{fr:["Faites tremper séparément shiitakes, coquilles Saint-Jacques séchées et crevettes séchées, une nuit ; gardez toutes les eaux de trempage.","Blanchissez chaque viande à part, rincez-la, puis faites-la revenir brièvement au gingembre.","Rangez les ingrédients dans une jarre en couches, du plus long à cuire au plus délicat : viandes au fond, fruits de mer au-dessus.","Versez le vin de riz, le bouillon et les eaux de trempage filtrées, sans remplir plus qu'aux trois quarts.","Scellez la jarre d'un papier huilé et d'une ficelle, et cuisez 5 heures à la vapeur douce. Ouvrez à table : le parfum est la moitié du plat."],
     en:["Soak the shiitake, dried scallops and dried shrimp separately overnight; keep all the soaking liquids.","Blanch each meat separately, rinse it, then fry it briefly with ginger.","Layer the ingredients in a jar, longest-cooking at the bottom, most delicate on top: meats below, seafood above.","Pour in the rice wine, broth and strained soaking liquids, filling no more than three quarters.","Seal the jar with oiled paper and string, and steam gently for 5 hours. Open it at the table: the scent is half the dish."]} },

{ id:'guoqiao-mixian', c:'as', lat:24.881, lon:102.833, base:4, prep:30, cook:120, diff:2, tags:['noodles','soup','comfort'],
  art:{v:'bowl',bg:'#33301f',plate:'#f4ecd8',style:'noodle',food:['#f0e8d0','#e0b45a','#7fae5a','#c9402c'],garnish:'#7fae6a'},
  n:{fr:'Nouilles du pont qui traverse',en:'Crossing-the-bridge noodles'},
  p:{fr:'Mengzi, Yunnan, Chine',en:'Mengzi, Yunnan, China'},
  d:{fr:"Un bouillon si gras qu'une pellicule d'huile le garde brûlant, dans lequel on plonge à table viandes crues et légumes. Une femme portait ainsi le repas à son mari, qui étudiait sur une île — le pont était long, la soupe restait chaude.",
     en:"A broth so rich that a film of oil keeps it scalding, into which raw meats and vegetables are dipped at the table. A wife carried her husband's meal this way to an island where he studied — the bridge was long, the soup stayed hot."},
  i:[['rice_noodles',400,'g'],['chicken',1,'kg'],['pork_bones',500,'g'],['chicken_breast',200,'g'],['pork_loin',200,'g'],['quail_egg',8,'pc'],['shiitake_mushrooms',150,'g'],['bean_sprouts',200,'g'],['chives',1,'bunch'],['ginger',40,'g'],['scallion',4,'pc'],['chili_oil',3,'tbsp'],['salt',null,'']],
  s:{fr:["Faites mijoter poulet et os de porc 2 heures avec gingembre et ciboule, puis filtrez : le bouillon doit rester gras en surface.","Tranchez les viandes crues en lamelles quasi transparentes, à moins de 2 mm : c'est la condition pour qu'elles cuisent au contact.","Disposez viandes, champignons, germes et ciboulette crus sur des assiettes séparées.","Cuisez les nouilles de riz et gardez-les au chaud dans un bol à part.","Portez le bouillon à 95 °C, versez-le dans un grand bol brûlant, et plongez-y les ingrédients à table : viandes d'abord, nouilles en dernier."],
     en:["Simmer the chicken and pork bones for 2 hours with ginger and spring onion, then strain: the broth must keep a layer of fat on top.","Slice the raw meats almost transparently thin, under 2 mm: that is what allows them to cook on contact.","Arrange the raw meats, mushrooms, sprouts and chives on separate plates.","Cook the rice noodles and keep them warm in a separate bowl.","Bring the broth to 95°C, pour it into a large scalding bowl, and add the ingredients at the table: meats first, noodles last."]} },

{ id:'suan-cai-yu', c:'as', lat:45.803, lon:126.535, base:4, prep:30, cook:40, diff:2, tags:['sea','comfort','stew'],
  art:{v:'pot',bg:'#2f3328',plate:'#f4ecd8',style:'fish',food:['#f0e8d0','#e8dcb8','#7fae5a','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Poisson au chou fermenté du Dongbei',en:'Dongbei fish with sour cabbage'},
  p:{fr:'Harbin, Heilongjiang, Chine',en:'Harbin, Heilongjiang, China'},
  d:{fr:"Du poisson d'eau douce mijoté avec du chou chinois fermenté dans de grands pots de terre. Le Nord-Est chinois fermente son chou par tonneaux entiers avant l'hiver, comme la Pologne ou l'Alsace, et pour la même raison.",
     en:"Freshwater fish stewed with fermented Chinese cabbage in large earthenware pots. China's north-east ferments cabbage by the barrel before winter, like Poland or Alsace, and for the same reason."},
  i:[['whitefish',1,'kg'],['fermented_cabbage',600,'g'],['pork_belly',200,'g'],['glass_noodles',150,'g'],['firm_tofu',300,'g'],['ginger',40,'g'],['garlic',6,'clove'],['scallion',4,'pc'],['rice_wine',80,'ml'],['soy_sauce',3,'tbsp'],['chicken_broth',1.2,'l'],['peanut_oil',80,'ml'],['white_pepper',1,'tsp'],['salt',null,'']],
  s:{fr:["Rincez le chou fermenté, pressez-le et taillez-le en lanières très fines : plus il est fin, plus il donne son acidité au bouillon.","Faites revenir la poitrine de porc en lardons jusqu'à ce qu'elle rende sa graisse, ajoutez gingembre, ail et ciboule.","Ajoutez le chou et faites-le sauter 10 minutes à feu vif : cette étape sèche est ce qui concentre le goût.","Versez le vin de riz, la sauce soja et le bouillon, et laissez mijoter 20 minutes.","Glissez le poisson en tronçons, le tofu et les vermicelles, et pochez 10 minutes sans remuer. Poivrez au poivre blanc."],
     en:["Rinse the fermented cabbage, squeeze it and cut it into very fine shreds: the finer it is, the more sourness it gives the broth.","Fry the pork belly in lardons until it renders its fat, then add ginger, garlic and spring onion.","Add the cabbage and stir-fry for 10 minutes over high heat: this dry stage is what concentrates the flavour.","Pour in the rice wine, soy sauce and broth, and simmer for 20 minutes.","Slide in the fish sections, the tofu and the glass noodles, and poach for 10 minutes without stirring. Season with white pepper."]} },

{ id:'thukpa-tibetain', c:'as', lat:29.652, lon:91.172, base:4, prep:30, cook:60, diff:1, tags:['noodles','soup','comfort'],
  art:{v:'bowl',bg:'#2f3328',plate:'#f0e4c8',style:'noodle',food:['#e8dcb8','#c9754a','#7fae5a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Thukpa',en:'Thukpa'},
  p:{fr:'Lhassa, Tibet, Chine',en:'Lhasa, Tibet, China'},
  d:{fr:"Une soupe de nouilles étirées à la main au bouillon de yak, épaissie de farine d'orge grillée. À quatre mille mètres, l'eau bout à 87 °C : tout se cuit longtemps, et rien ne se mange froid.",
     en:"A soup of hand-pulled noodles in yak broth, thickened with roasted barley flour. At four thousand metres water boils at 87°C: everything cooks slowly, and nothing is eaten cold."},
  i:[['flour',350,'g'],['water',180,'ml'],['beef_chuck',500,'g'],['onion',2,'pc'],['carrot',2,'pc'],['daikon_radish',300,'g'],['ginger',40,'g'],['garlic',5,'clove'],['barley_flour',3,'tbsp'],['cilantro',1,'bunch'],['sichuan_pepper',1,'tsp'],['scallion',4,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pétrissez la farine, l'eau et le sel 15 minutes, huilez la pâte et laissez-la reposer une heure sous un bol.","Faites mijoter le bœuf en cubes 45 minutes avec gingembre, ail et poivre du Sichuan.","Ajoutez oignon, carotte et radis blanc en gros morceaux, et poursuivez 20 minutes.","Étirez la pâte à la main en longs rubans, en la tirant et la repliant plusieurs fois, puis jetez-les directement dans le bouillon.","Laissez cuire 5 minutes, liez d'une cuillerée de farine d'orge délayée, et couvrez de coriandre et de ciboule."],
     en:["Knead the flour, water and salt for 15 minutes, oil the dough and rest it for an hour under a bowl.","Simmer the diced beef for 45 minutes with ginger, garlic and Sichuan pepper.","Add the onion, carrot and daikon in large pieces, and continue for 20 minutes.","Pull the dough by hand into long ribbons, stretching and folding it several times, then drop them straight into the broth.","Cook for 5 minutes, thicken with a spoonful of slaked barley flour, and cover with coriander and spring onion."]} },

{ id:'wenchang-ji', c:'as', lat:19.543, lon:110.797, base:6, prep:30, cook:60, diff:2, tags:['poultry','festive','fresh'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'grill',food:['#f0e0a8','#e8c46a','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Poulet de Wenchang',en:'Wenchang chicken'},
  p:{fr:'Wenchang, Hainan, Chine',en:'Wenchang, Hainan, China'},
  d:{fr:"Un poulet poché à peine, refroidi à l'eau glacée pour que la peau devienne gélatineuse, servi froid avec une sauce au gingembre. C'est l'ancêtre direct du riz au poulet hainanais de Singapour.",
     en:"A chicken barely poached, then plunged into iced water so the skin turns gelatinous, and served cold with ginger sauce. It is the direct ancestor of Singapore's Hainanese chicken rice."},
  i:[['chicken',1.6,'kg'],['ginger',100,'g'],['scallion',8,'pc'],['coarse_salt',3,'tbsp'],['peanut_oil',120,'ml'],['long_grain_rice',400,'g'],['garlic',6,'clove'],['soy_sauce',60,'ml'],['lime',2,'pc'],['ice',20,'pc'],['cilantro',1,'bunch'],['salt',null,'']],
  s:{fr:["Frottez le poulet de gros sel à l'intérieur et à l'extérieur, et laissez-le une heure à température ambiante.","Plongez-le dans une grande eau frémissante avec gingembre et ciboule, coupez le feu et laissez pocher 40 minutes à couvert, sans jamais bouillir.","Sortez-le et plongez-le aussitôt dans un bain d'eau glacée dix minutes : la peau se rétracte et devient ferme et translucide.","Faites cuire le riz dans le bouillon de pochage avec l'ail et un peu de graisse de poulet.","Hachez gingembre et ciboule très fin, salez, et versez dessus l'huile fumante. Découpez le poulet froid et servez avec la sauce et le riz."],
     en:["Rub the chicken with coarse salt inside and out, and leave it for an hour at room temperature.","Lower it into a large pan of simmering water with ginger and spring onion, cut the heat and poach covered for 40 minutes, never boiling.","Lift it out and plunge it straight into an iced water bath for ten minutes: the skin contracts and turns firm and translucent.","Cook the rice in the poaching broth with the garlic and a little chicken fat.","Chop the ginger and spring onion very finely, salt them, and pour smoking oil over. Carve the cold chicken and serve with the sauce and rice."]} },

{ id:'okonomiyaki', c:'as', lat:34.385, lon:132.455, base:4, prep:30, cook:25, diff:2, tags:['street','comfort','pork'],
  art:{v:'board',bg:'#33291f',plate:'#f2e6c8',style:'flat',food:['#e8c46a','#8f5a3a','#c9402c','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Okonomiyaki de Hiroshima',en:'Hiroshima okonomiyaki'},
  p:{fr:'Hiroshima, Japon',en:'Hiroshima, Japan'},
  d:{fr:"À Hiroshima, la galette n'est pas mélangée mais montée en couches : crêpe, montagne de chou, nouilles, œuf. La version d'Osaka mélange tout ; les deux villes s'en disputent depuis soixante-dix ans.",
     en:"In Hiroshima the pancake is not mixed but built in layers: crêpe, mountain of cabbage, noodles, egg. The Osaka version mixes everything; the two cities have argued about it for seventy years."},
  i:[['flour',150,'g'],['water',200,'ml'],['cabbage',600,'g'],['bean_sprouts',200,'g'],['smoked_bacon',200,'g'],['ramen_noodles',300,'g'],['egg',4,'pc'],['takoyaki_sauce',6,'tbsp'],['mayonnaise',4,'tbsp'],['bonito_flakes',20,'g'],['scallion',4,'pc'],['nori',2,'pc'],['peanut_oil',60,'ml'],['salt',null,'']],
  s:{fr:["Fouettez la farine et l'eau en une pâte fluide et laissez-la reposer 30 minutes.","Versez une louche sur la plaque et étalez-la en cercle fin ; posez dessus une montagne de chou finement émincé et de germes.","Ajoutez les tranches de lard, versez un filet de pâte pour lier, et retournez le tout d'un coup — c'est le geste difficile.","Laissez cuire 8 minutes à couvert : le chou fond de moitié à la vapeur.","À côté, faites sauter les nouilles avec un peu de sauce, cassez un œuf en omelette fine, empilez nouilles, galette et œuf, puis nappez de sauce et de mayonnaise."],
     en:["Whisk the flour and water into a thin batter and rest it for 30 minutes.","Pour a ladle onto the griddle and spread it into a thin circle; pile finely shredded cabbage and sprouts on top.","Lay on the bacon slices, drizzle a little batter to bind, and flip the whole thing in one movement — this is the difficult part.","Cook covered for 8 minutes: the cabbage halves in volume as it steams.","Alongside, fry the noodles with a little sauce, cook an egg into a thin omelette, stack noodles, pancake and egg, then coat with sauce and mayonnaise."]} },

{ id:'oden', c:'as', lat:35.011, lon:135.768, base:6, prep:40, cook:120, diff:2, tags:['comfort','soup','slow'],
  art:{v:'pot',bg:'#2c3440',plate:'#f4ecd8',style:'soup',food:['#f0e8d0','#e8dcc0','#c9a878','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Oden',en:'Oden'},
  p:{fr:'Kyoto, Japon',en:'Kyoto, Japan'},
  d:{fr:"Un pot-au-feu japonais où chaque ingrédient mijote des heures dans un bouillon clair de dashi et de soja. On le vend l'hiver dans les supérettes, et chacun choisit à la pince ce qu'il veut dans le bac fumant.",
     en:"A Japanese one-pot in which each ingredient simmers for hours in a clear dashi and soy broth. It is sold in convenience stores in winter, and everyone picks with tongs from the steaming tray."},
  i:[['dashi_stock',2,'l'],['soy_sauce',80,'ml'],['mirin',80,'ml'],['daikon_radish',800,'g'],['egg',6,'pc'],['firm_tofu',400,'g'],['konjac',300,'g'],['fish_cake',400,'g'],['octopus',300,'g'],['kombu',20,'g'],['mustard',3,'tbsp'],['sugar',1,'tbsp'],['salt',null,'']],
  s:{fr:["Épluchez le radis blanc en tronçons épais, arrondissez les arêtes au couteau et faites-le précuire 30 minutes à l'eau de riz : il perd son amertume.","Préparez le bouillon avec le dashi, la sauce soja, le mirin et le sucre ; il doit rester clair et à peine salé.","Faites cuire les œufs durs, blanchissez le konjac et grillez brièvement le tofu.","Rangez les ingrédients par temps de cuisson : radis et poulpe d'abord, deux heures ; œufs et tofu ensuite ; pâtes de poisson en dernier.","Ne faites jamais bouillir : le bouillon doit à peine frémir. Servez avec une pointe de moutarde jaune."],
     en:["Peel the daikon into thick rounds, bevel the edges with a knife and pre-cook it for 30 minutes in rice water: it loses its bitterness.","Make the broth with dashi, soy sauce, mirin and sugar; it should stay clear and barely salty.","Hard-boil the eggs, blanch the konjac and briefly grill the tofu.","Add the ingredients by cooking time: daikon and octopus first, for two hours; eggs and tofu next; fish cakes last.","Never let it boil: the broth should barely tremble. Serve with a dab of yellow mustard."]} },

{ id:'unadon', c:'as', lat:34.710, lon:137.726, base:4, prep:30, cook:30, diff:3, tags:['sea','rice','festive'],
  art:{v:'bowl',bg:'#2b2419',plate:'#f4ecd8',style:'rice',food:['#6f4a2a','#8f5a2b','#f4f0e6','#3a2a1a'],garnish:'#7fae6a'},
  n:{fr:'Unadon',en:'Unadon'},
  p:{fr:'Hamamatsu, Shizuoka, Japon',en:'Hamamatsu, Shizuoka, Japan'},
  d:{fr:"De l'anguille grillée et laquée sur un bol de riz, mangée le jour du Bœuf du milieu de l'été pour résister à la chaleur. La sauce des vieilles maisons n'est jamais jetée : on la complète depuis des générations.",
     en:"Grilled lacquered eel over a bowl of rice, eaten on the midsummer Day of the Ox to withstand the heat. The sauce in old houses is never thrown away: it has been topped up for generations."},
  i:[['eel',800,'g'],['soy_sauce',150,'ml'],['mirin',150,'ml'],['sugar',60,'g'],['rice_wine',80,'ml'],['sushi_rice',400,'g'],['sichuan_pepper',1,'tsp'],['scallion',3,'pc'],['salt',null,'']],
  s:{fr:["Faites réduire de moitié la sauce soja, le mirin, le saké et le sucre : c'est la tare, le fond de sauce.","Ouvrez l'anguille en portefeuille, retirez l'arête et coupez-la en tronçons de la taille du bol.","Faites-la cuire d'abord à la vapeur 10 minutes, côté chair : c'est ce qui la rend fondante et fait fondre la graisse.","Grillez-la ensuite sur la braise, en la trempant trois fois dans la tare entre chaque passage, jusqu'à ce que la laque brille.","Dressez sur le riz vinaigré chaud, arrosez d'une cuillerée de sauce et poudrez de poivre sanshō."],
     en:["Reduce the soy sauce, mirin, sake and sugar by half: this is the tare, the base sauce.","Butterfly the eel, remove the backbone and cut it into bowl-sized sections.","Steam it first for 10 minutes, flesh side up: this is what makes it melting and renders the fat.","Then grill it over embers, dipping it three times in the tare between passes, until the lacquer shines.","Serve over hot vinegared rice, spoon over a little sauce and dust with sanshō pepper."]} },

{ id:'kaiseki-chawanmushi', c:'as', lat:35.181, lon:136.907, base:4, prep:25, cook:20, diff:3, tags:['sea','fresh','festive'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'soup',food:['#f0e0a8','#f4f0e6','#e0b45a','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Chawanmushi',en:'Chawanmushi'},
  p:{fr:'Nagoya, Aichi, Japon',en:'Nagoya, Aichi, Japan'},
  d:{fr:"Un flan salé au dashi, cuit à la vapeur dans une tasse à couvercle, si tendre qu'il faut le manger à la cuillère. C'est le seul plat japonais que l'on mange chaud à la cuillère, et cela suffit à le rendre singulier.",
     en:"A savoury dashi custard steamed in a lidded cup, so tender it must be eaten with a spoon. It is the only Japanese dish eaten hot with a spoon, and that alone makes it singular."},
  i:[['egg',4,'pc'],['dashi_stock',600,'ml'],['soy_sauce',2,'tsp'],['mirin',2,'tsp'],['chicken_breast',150,'g'],['shrimp',8,'pc'],['shiitake_mushrooms',4,'pc'],['ginkgo_nuts',12,'pc'],['spring_onion',2,'pc'],['salt',null,'']],
  s:{fr:["Battez les œufs sans les faire mousser : la moindre bulle donnerait une texture grumeleuse.","Mêlez-les au dashi refroidi, à la sauce soja et au mirin, dans un rapport d'un volume d'œuf pour trois de bouillon.","Passez l'appareil au chinois fin, deux fois : c'est ce qui donne le velouté.","Répartissez poulet, crevettes, shiitakes et noix de ginkgo au fond des tasses, versez l'appareil et couvrez.","Cuisez 12 minutes à la vapeur douce, feu très bas et couvercle entrouvert : au-delà de 85 °C, le flan se troue."],
     en:["Beat the eggs without frothing them: the smallest bubble would give a grainy texture.","Mix them with the cooled dashi, soy sauce and mirin, in a ratio of one part egg to three parts broth.","Pass the mixture through a fine sieve, twice: that is what gives the velvet texture.","Divide chicken, prawns, shiitake and ginkgo nuts between the cups, pour in the mixture and cover.","Steam for 12 minutes over gentle heat with the lid ajar: above 85°C the custard turns holey."]} },

{ id:'motsunabe', c:'as', lat:33.590, lon:130.402, base:4, prep:40, cook:45, diff:2, tags:['comfort','soup','beef'],
  art:{v:'pot',bg:'#2f3328',plate:'#f0e4c8',style:'soup',food:['#7fae5a','#c9754a','#f0e8d0','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Motsunabe',en:'Motsunabe'},
  p:{fr:'Fukuoka, Kyushu, Japon',en:'Fukuoka, Kyushu, Japan'},
  d:{fr:"Une marmite de tripes de bœuf, de chou et de ciboulette dans un bouillon à l'ail et au piment. Née après-guerre à Fukuoka, quand les abats étaient tout ce qu'on trouvait, elle est devenue le plat d'hiver de la ville.",
     en:"A pot of beef tripe, cabbage and garlic chives in a broth of garlic and chilli. Born in post-war Fukuoka, when offal was all there was, it became the city's winter dish."},
  i:[['beef_tripe',700,'g'],['cabbage',600,'g'],['garlic_chives',2,'bunch'],['bean_sprouts',200,'g'],['firm_tofu',300,'g'],['garlic',10,'clove'],['ginger',40,'g'],['dashi_stock',1.5,'l'],['soy_sauce',80,'ml'],['miso_paste',3,'tbsp'],['chili_flakes',2,'tsp'],['sesame_seeds',3,'tbsp'],['ramen_noodles',200,'g'],['salt',null,'']],
  s:{fr:["Blanchissez les tripes 10 minutes, rincez-les à l'eau froide et taillez-les en morceaux de 4 cm.","Faites-les cuire 40 minutes dans le dashi avec la moitié de l'ail et le gingembre, jusqu'à ce qu'elles s'attendrissent.","Assaisonnez le bouillon de sauce soja et de miso, sans le faire bouillir après le miso.","Rangez dans la marmite le chou en gros morceaux, le tofu et les tripes, et couronnez d'une montagne de ciboulette chinoise et d'ail émincé.","Portez à frémissement à table, 10 minutes. Finissez le bouillon avec des nouilles ramen — c'est le shime, la clôture du repas."],
     en:["Blanch the tripe for 10 minutes, rinse it in cold water and cut it into 4 cm pieces.","Cook it for 40 minutes in the dashi with half the garlic and the ginger, until tender.","Season the broth with soy sauce and miso, without boiling it once the miso is in.","Arrange the cabbage in large pieces, the tofu and the tripe in the pot, and crown with a mountain of garlic chives and sliced garlic.","Bring to a simmer at the table for 10 minutes. Finish the broth with ramen noodles — the shime, the closing of the meal."]} },

{ id:'zunda-mochi', c:'as', lat:38.268, lon:140.870, base:6, prep:40, cook:20, diff:2, tags:['sweet','veg','festive'],
  art:{v:'plate',bg:'#28331f',plate:'#f4ead4',style:'cake',food:['#7fae5a','#4f8f4a','#f4f0e6','#e8dcc0'],garnish:'#6fbf8f'},
  n:{fr:'Zunda mochi',en:'Zunda mochi'},
  p:{fr:'Sendai, Miyagi, Japon',en:'Sendai, Miyagi, Japan'},
  d:{fr:"Des gâteaux de riz gluant sous une purée sucrée d'edamame d'un vert éclatant. Le nom viendrait de zuda, le pilon : les paysans du Tōhoku écrasaient les fèves fraîches au mortier après la récolte d'été.",
     en:"Glutinous rice cakes under a sweetened purée of edamame, brilliant green. The name may come from zuda, the pestle: Tōhoku farmers pounded fresh beans in a mortar after the summer harvest."},
  i:[['glutinous_rice',400,'g'],['fava_beans',600,'g'],['sugar',120,'g'],['water',400,'ml'],['potato_starch',3,'tbsp'],['salt',null,'']],
  s:{fr:["Faites tremper le riz gluant une nuit, puis cuisez-le à la vapeur 40 minutes sur un linge.","Écossez les edamame, blanchissez-les 4 minutes et retirez la seconde peau de chaque fève — c'est fastidieux, et c'est ce qui donne la couleur.","Pilez les fèves au mortier avec le sucre et une pincée de sel, en ajoutant un peu d'eau : la purée doit rester légèrement granuleuse.","Pilez le riz chaud au mortier jusqu'à ce qu'il devienne une masse élastique et sans grain visible.","Formez des boules à la main mouillée de fécule et nappez-les de purée verte. À manger le jour même."],
     en:["Soak the glutinous rice overnight, then steam it for 40 minutes over a cloth.","Pod the edamame, blanch them for 4 minutes and slip the second skin off each bean — tedious, and what gives the colour.","Pound the beans in a mortar with the sugar and a pinch of salt, adding a little water: the purée should stay slightly grainy.","Pound the hot rice in a mortar until it becomes an elastic mass with no visible grain.","Shape balls with hands wetted in starch and coat them in the green purée. Eat the same day."]} },

{ id:'samgyetang', c:'as', lat:37.567, lon:126.978, base:2, prep:30, cook:90, diff:2, tags:['poultry','soup','slow'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'soup',food:['#f4f0e6','#f0e8d0','#e8dcc0','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Samgyetang',en:'Samgyetang'},
  p:{fr:'Séoul, Corée du Sud',en:'Seoul, South Korea'},
  d:{fr:"Une poule entière farcie de riz gluant, de ginseng et de jujubes, pochée jusqu'à s'effondrer. On le mange les jours les plus chauds de l'été — la logique coréenne veut qu'on combatte la chaleur par la chaleur.",
     en:"A whole young chicken stuffed with glutinous rice, ginseng and jujubes, poached until it collapses. It is eaten on the hottest days of summer — Korean logic holds that heat is fought with heat."},
  i:[['chicken',1.2,'kg'],['glutinous_rice',150,'g'],['ginseng',2,'pc'],['jujube',6,'pc'],['garlic',10,'clove'],['chestnuts',6,'pc'],['scallion',4,'pc'],['ginger',30,'g'],['water',2,'l'],['sesame_seeds',2,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper le riz gluant 2 heures, puis égouttez-le.","Nettoyez soigneusement l'intérieur du poulet et farcissez-le de riz, de ginseng, de jujubes, d'ail et de châtaignes, aux deux tiers seulement.","Refermez l'ouverture en croisant les pattes, ou cousez-la : le riz gonfle et sortirait sinon.","Couvrez d'eau froide, portez à frémissement et écumez, puis laissez pocher 1 h 15 sans jamais bouillir.","Servez le poulet entier dans son bouillon, sans sel : chacun sale au poivre et au sel dans une soucoupe, à sa main."],
     en:["Soak the glutinous rice for 2 hours, then drain it.","Clean the inside of the chicken thoroughly and stuff it with rice, ginseng, jujubes, garlic and chestnuts, filling only two thirds.","Close the opening by crossing the legs, or sew it: the rice swells and would otherwise escape.","Cover with cold water, bring to a simmer and skim, then poach for 1¼ hours without ever boiling.","Serve the whole chicken in its broth, unsalted: each diner seasons from a saucer of salt and pepper, to taste."]} },

{ id:'jjajangmyeon', c:'as', lat:37.456, lon:126.705, base:4, prep:30, cook:30, diff:2, tags:['noodles','comfort','fast'],
  art:{v:'bowl',bg:'#2b2419',plate:'#f4ecd8',style:'noodle',food:['#3a2a2a','#f4f0e6','#7fae5a','#e8dcc0'],garnish:'#7fae6a'},
  n:{fr:'Jjajangmyeon',en:'Jjajangmyeon'},
  p:{fr:'Incheon, Corée du Sud',en:'Incheon, South Korea'},
  d:{fr:"Des nouilles sous une sauce noire de pâte de soja frite, de porc et d'oignon. Née dans le quartier chinois d'Incheon vers 1905, elle est devenue si coréenne que le 14 avril, les célibataires la mangent en noir.",
     en:"Noodles under a black sauce of fried soybean paste, pork and onion. Born in Incheon's Chinatown around 1905, it became so Korean that on 14 April single people eat it dressed in black."},
  i:[['wheat_noodles',500,'g'],['pork_belly',400,'g'],['onion',600,'g'],['zucchini',200,'g'],['potato',200,'g'],['chunjang',6,'tbsp'],['peanut_oil',120,'ml'],['potato_starch',3,'tbsp'],['sugar',2,'tbsp'],['rice_wine',3,'tbsp'],['cucumber',1,'pc'],['ginger',30,'g'],['salt',null,'']],
  s:{fr:["Faites frire la pâte de soja noire dans l'huile 4 minutes à feu doux : c'est cette étape qui lui retire son amertume, et on ne peut pas la sauter.","Faites revenir le porc en dés avec le gingembre, puis ajoutez oignon, courgette et pomme de terre en petits cubes.","Laissez suer 10 minutes : l'oignon doit rendre son sucre et la sauce en dépendra.","Ajoutez la pâte frite et un verre d'eau, laissez mijoter 10 minutes, puis liez à la fécule délayée.","Cuisez les nouilles, dressez-les, versez la sauce dessus et couronnez de concombre en fine julienne."],
     en:["Fry the black bean paste in oil for 4 minutes over low heat: this step removes its bitterness, and cannot be skipped.","Fry the diced pork with the ginger, then add the onion, courgette and potato in small cubes.","Sweat for 10 minutes: the onion must give up its sugar, and the sauce depends on it.","Add the fried paste and a glass of water, simmer for 10 minutes, then thicken with slaked starch.","Cook the noodles, plate them, pour the sauce over and crown with finely julienned cucumber."]} },

{ id:'galbijjim', c:'as', lat:35.180, lon:129.076, base:6, prep:40, cook:150, diff:2, tags:['beef','slow','festive'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#8f5a3a','#e0913a','#c9a878'],garnish:'#7fae6a'},
  n:{fr:'Galbijjim',en:'Galbijjim'},
  p:{fr:'Busan, Corée du Sud',en:'Busan, South Korea'},
  d:{fr:"Des travers de bœuf braisés dans une sauce soja sucrée, avec radis, carottes, jujubes et châtaignes. Plat des grandes occasions coréennes, il se sert à Chuseok et aux mariages, jamais un jour ordinaire.",
     en:"Beef short ribs braised in a sweet soy sauce with radish, carrot, jujubes and chestnuts. A dish for great Korean occasions, served at Chuseok and weddings, never on an ordinary day."},
  i:[['beef_short_ribs',1.5,'kg'],['soy_sauce',150,'ml'],['pear',1,'pc'],['onion',2,'pc'],['garlic',10,'clove'],['ginger',40,'g'],['brown_sugar',60,'g'],['sesame_oil',3,'tbsp'],['daikon_radish',400,'g'],['carrot',300,'g'],['jujube',8,'pc'],['chestnuts',10,'pc'],['shiitake_mushrooms',150,'g'],['scallion',4,'pc'],['sesame_seeds',2,'tbsp'],['pepper',null,'']],
  s:{fr:["Faites dégorger les travers 2 heures à l'eau froide en la changeant deux fois : c'est ce qui donnera une sauce claire.","Blanchissez-les 10 minutes, jetez l'eau et rincez soigneusement chaque morceau.","Mixez la poire, l'oignon, l'ail et le gingembre : les enzymes de la poire attendrissent la viande mieux que toute cuisson.","Mêlez cette purée à la sauce soja et au sucre, versez sur la viande et laissez mariner 4 heures.","Braisez 1 h 30 à couvert, puis ajoutez radis, carottes tournées, jujubes, châtaignes et champignons pour 40 minutes."],
     en:["Soak the ribs for 2 hours in cold water, changing it twice: this is what gives a clear sauce.","Blanch them for 10 minutes, discard the water and rinse each piece carefully.","Blend the pear, onion, garlic and ginger: the pear's enzymes tenderise the meat better than any amount of cooking.","Mix this purée with the soy sauce and sugar, pour it over the meat and marinate for 4 hours.","Braise covered for 1½ hours, then add the radish, turned carrots, jujubes, chestnuts and mushrooms for 40 minutes."]} },

{ id:'haemul-pajeon', c:'as', lat:35.160, lon:129.062, base:4, prep:25, cook:20, diff:2, tags:['sea','street','fast'],
  art:{v:'board',bg:'#28331f',plate:'#f2e6c8',style:'flat',food:['#e8c46a','#4f8f4a','#f0a878','#f2dfa8'],garnish:'#6fbf8f'},
  n:{fr:'Haemul pajeon',en:'Haemul pajeon'},
  p:{fr:'Busan, Corée du Sud',en:'Busan, South Korea'},
  d:{fr:"Une galette de ciboules entières et de fruits de mer, croustillante au bord et moelleuse au centre. Les Coréens la mangent les jours de pluie : le bruit de la friture, dit-on, ressemble à celui de l'averse.",
     en:"A pancake of whole spring onions and seafood, crisp at the edge and soft at the centre. Koreans eat it on rainy days: the sound of the frying, they say, resembles the sound of the downpour."},
  i:[['scallion',12,'pc'],['shrimp',200,'g'],['squid',200,'g'],['clams',200,'g'],['flour',200,'g'],['rice_flour',80,'g'],['ice_water',350,'ml'],['egg',2,'pc'],['peanut_oil',150,'ml'],['soy_sauce',4,'tbsp'],['rice_vinegar',2,'tbsp'],['chili_flakes',1,'tsp'],['sesame_seeds',1,'tbsp'],['salt',null,'']],
  s:{fr:["Fouettez les farines dans l'eau glacée sans trop travailler : quelques grumeaux valent mieux qu'une pâte élastique.","La pâte doit rester fluide et très froide — c'est le choc thermique avec l'huile qui fait le croustillant.","Rangez les ciboules entières côte à côte dans la poêle huilée bien chaude, en une seule couche serrée.","Versez la pâte dessus, répartissez les fruits de mer, puis versez l'œuf battu par-dessus.","Faites cuire 6 minutes sans y toucher, retournez d'un bloc et pressez à la spatule 5 minutes. Servez avec la sauce soja au vinaigre."],
     en:["Whisk the flours into iced water without overworking: a few lumps are better than an elastic batter.","The batter must stay thin and very cold — it is the thermal shock with the oil that makes it crisp.","Lay the whole spring onions side by side in a hot oiled pan, in a single tight layer.","Pour the batter over them, scatter the seafood, then pour the beaten egg on top.","Cook for 6 minutes untouched, flip it in one piece and press with a spatula for 5 minutes. Serve with the soy and vinegar sauce."]} },

{ id:'dakgalbi', c:'as', lat:37.881, lon:127.730, base:4, prep:30, cook:25, diff:1, tags:['poultry','spicy','street'],
  art:{v:'pot',bg:'#33251c',plate:'#f2e8d0',style:'grill',food:['#c9402c','#8f3b2a','#7fae5a','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Dakgalbi',en:'Dakgalbi'},
  p:{fr:'Chuncheon, Gangwon, Corée du Sud',en:'Chuncheon, Gangwon, South Korea'},
  d:{fr:"Du poulet mariné au gochujang, sauté à table sur une plaque avec chou, patate douce et gâteaux de riz. Né à Chuncheon dans les années 1960 comme alternative bon marché au porc, il est devenu le plat des étudiants.",
     en:"Chicken marinated in gochujang, stir-fried at the table on a hotplate with cabbage, sweet potato and rice cakes. Born in Chuncheon in the 1960s as a cheap alternative to pork, it became the students' dish."},
  i:[['chicken_thighs',800,'g'],['gochujang',5,'tbsp'],['gochugaru',2,'tbsp'],['soy_sauce',3,'tbsp'],['rice_wine',3,'tbsp'],['garlic',8,'clove'],['ginger',30,'g'],['brown_sugar',2,'tbsp'],['cabbage',400,'g'],['sweet_potato',300,'g'],['rice_cakes',300,'g'],['scallion',6,'pc'],['sesame_oil',2,'tbsp'],['perilla_leaves',10,'pc'],['salt',null,'']],
  s:{fr:["Désossez les cuisses et taillez-les en morceaux de 4 cm, en gardant la peau.","Mêlez gochujang, gochugaru, soja, saké, ail, gingembre et sucre, et faites mariner le poulet 4 heures.","Faites tremper les gâteaux de riz 20 minutes à l'eau tiède pour qu'ils s'assouplissent.","Chauffez une large plaque, versez le poulet et sa marinade, et laissez saisir sans remuer 5 minutes.","Ajoutez chou, patate douce et gâteaux de riz, et faites sauter 15 minutes. Terminez par les feuilles de périlla et l'huile de sésame."],
     en:["Bone the thighs and cut them into 4 cm pieces, keeping the skin.","Mix the gochujang, gochugaru, soy, sake, garlic, ginger and sugar, and marinate the chicken for 4 hours.","Soak the rice cakes for 20 minutes in warm water so they soften.","Heat a wide plate, tip in the chicken and its marinade, and let it sear without stirring for 5 minutes.","Add the cabbage, sweet potato and rice cakes, and stir-fry for 15 minutes. Finish with perilla leaves and sesame oil."]} },

{ id:'yukhoe', c:'as', lat:35.872, lon:128.601, base:4, prep:25, cook:0, diff:2, tags:['beef','fresh','fast'],
  art:{v:'plate',bg:'#33251c',plate:'#f2e8d0',style:'salad',food:['#8f1a3a','#e8c46a','#f4f0e6','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Yukhoe',en:'Yukhoe'},
  p:{fr:'Daegu, Corée du Sud',en:'Daegu, South Korea'},
  d:{fr:"Du bœuf cru taillé en fins bâtonnets, assaisonné à l'huile de sésame et couronné d'un jaune d'œuf. La poire coréenne râpée n'est pas décorative : ses enzymes attendrissent la viande pendant qu'elle attend.",
     en:"Raw beef cut into fine batons, dressed with sesame oil and crowned with an egg yolk. The grated Korean pear is not decorative: its enzymes tenderise the meat while it waits."},
  i:[['beef_sirloin',500,'g'],['pear',1,'pc'],['egg_yolk',4,'pc'],['sesame_oil',3,'tbsp'],['soy_sauce',2,'tbsp'],['brown_sugar',1,'tbsp'],['garlic',3,'clove'],['scallion',3,'pc'],['sesame_seeds',2,'tbsp'],['pine_nuts',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Choisissez une pièce de bœuf d'une fraîcheur irréprochable et gardez-la au congélateur 30 minutes : ferme, elle se tranche net.","Taillez-la en bâtonnets de 5 mm au couteau, dans le sens contraire des fibres, sans jamais la hacher.","Mêlez huile de sésame, soja, sucre, ail écrasé et ciboule ciselée, et assaisonnez la viande au dernier moment.","Râpez la poire en fine julienne et disposez-la au fond de l'assiette, en couronne.","Dressez le bœuf au centre, creusez un puits, posez-y le jaune d'œuf et parsemez de sésame et de pignons. Servez immédiatement."],
     en:["Choose beef of impeccable freshness and keep it in the freezer for 30 minutes: firm, it slices cleanly.","Cut it into 5 mm batons by knife, against the grain, never chopping it.","Mix the sesame oil, soy, sugar, crushed garlic and chopped spring onion, and dress the meat at the last moment.","Julienne the pear finely and lay it in a ring on the plate.","Mound the beef in the centre, hollow a well, set the egg yolk in it and scatter sesame and pine nuts. Serve immediately."]} },

{ id:'kongguksu', c:'as', lat:35.824, lon:127.148, base:4, prep:40, cook:20, diff:2, tags:['noodles','fresh','veg'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'noodle',food:['#f4f0e6','#f0e8d0','#7fae5a','#e8dcc0'],garnish:'#6fbf8f'},
  n:{fr:'Kongguksu',en:'Kongguksu'},
  p:{fr:'Jeonju, Jeolla, Corée du Sud',en:'Jeonju, Jeolla, South Korea'},
  d:{fr:"Des nouilles froides dans un lait de soja épais et non sucré, servies avec du concombre et de la glace. C'est le contraire du samgyetang : ici, on combat la chaleur de l'été par le froid le plus complet.",
     en:"Cold noodles in a thick unsweetened soy milk, served with cucumber and ice. The opposite of samgyetang: here summer heat is fought with the most complete cold."},
  i:[['soybeans',300,'g'],['wheat_noodles',400,'g'],['sesame_seeds',60,'g'],['pine_nuts',40,'g'],['cucumber',1,'pc'],['ripe_tomato',1,'pc'],['ice',12,'pc'],['water',800,'ml'],['salt',null,'']],
  s:{fr:["Faites tremper les graines de soja 8 heures, puis frottez-les entre les mains pour retirer les peaux, qui remontent à la surface.","Faites-les cuire 12 minutes seulement dans l'eau bouillante : trop cuites, elles perdent leur douceur et prennent un goût de farine.","Mixez-les longuement avec le sésame grillé, les pignons et l'eau froide, puis passez au tamis fin.","Réservez ce lait au réfrigérateur au moins 3 heures : il doit être glacé, pas seulement froid.","Cuisez les nouilles, rincez-les longuement à l'eau glacée, dressez-les, versez le lait de soja et ajoutez concombre, tomate et glaçons. Salez à table."],
     en:["Soak the soybeans for 8 hours, then rub them between your hands to remove the skins, which float to the surface.","Boil them for 12 minutes only: overcooked, they lose their sweetness and take on a floury taste.","Blend them at length with the toasted sesame, pine nuts and cold water, then pass through a fine sieve.","Chill this milk for at least 3 hours: it must be ice cold, not merely cool.","Cook the noodles, rinse them thoroughly in iced water, plate them, pour over the soy milk and add cucumber, tomato and ice cubes. Salt at the table."]} }
,
{ id:'laksa-sarawak', c:'as', lat:1.553, lon:110.359, base:4, prep:45, cook:60, diff:3, tags:['noodles','sea','spicy'],
  art:{v:'bowl',bg:'#33251c',plate:'#f2e8d0',style:'noodle',food:['#c9754a','#e0913a','#f0a878','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Laksa de Sarawak',en:'Sarawak laksa'},
  p:{fr:'Kuching, Sarawak, Malaisie',en:'Kuching, Sarawak, Malaysia'},
  d:{fr:"Ni curry ni assam : une troisième voie, à la pâte de sambal, au tamarin et au lait de coco, sur des vermicelles avec crevettes et poulet effiloché. Anthony Bourdain en avait fait son petit-déjeuner des dieux.",
     en:"Neither curry nor assam laksa: a third way, built on sambal paste, tamarind and coconut milk, over vermicelli with prawns and shredded chicken. Anthony Bourdain called it the breakfast of the gods."},
  i:[['rice_vermicelli',400,'g'],['shrimp',500,'g'],['chicken_breast',400,'g'],['coconut_milk',600,'ml'],['dried_chili',10,'pc'],['shallot',10,'pc'],['garlic',8,'clove'],['lemongrass',3,'pc'],['galangal',40,'g'],['candlenut',6,'pc'],['coriander_seeds',2,'tbsp'],['cumin',1,'tsp'],['tamarind_paste',3,'tbsp'],['shrimp_paste',2,'tbsp'],['egg',4,'pc'],['bean_sprouts',250,'g'],['cilantro',1,'bunch'],['lime',3,'pc'],['peanut_oil',120,'ml'],['salt',null,'']],
  s:{fr:["Décortiquez les crevettes et faites un fumet avec les têtes et les carapaces, 20 minutes, puis filtrez : c'est la base du bouillon.","Pochez le poulet dans ce fumet, retirez-le et effilochez-le à la main, jamais au couteau.","Pilez piments trempés, échalote, ail, citronnelle, galanga, noix de bancoul, coriandre, cumin et pâte de crevette en une pâte très fine.","Faites-la frire 15 minutes dans l'huile, jusqu'à ce qu'elle fonce et que l'huile se sépare.","Versez le fumet, le tamarin puis le lait de coco, et laissez frémir 20 minutes sans bouillir. Servez sur les vermicelles avec crevettes, poulet, omelette en lanières, germes et citron vert."],
     en:["Peel the prawns and make a stock with the heads and shells for 20 minutes, then strain it: this is the base of the broth.","Poach the chicken in that stock, lift it out and shred it by hand, never with a knife.","Pound the soaked chillies, shallot, garlic, lemongrass, galangal, candlenuts, coriander, cumin and shrimp paste into a very fine paste.","Fry it for 15 minutes in the oil, until it darkens and the oil separates.","Pour in the stock, the tamarind then the coconut milk, and simmer for 20 minutes without boiling. Serve over vermicelli with prawns, chicken, shredded omelette, sprouts and lime."]} },

{ id:'plov-samarkand', c:'as', lat:39.627, lon:66.975, base:8, prep:45, cook:120, diff:3, tags:['rice','lamb','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#e0b45a','#c98a2c','#8f5a3a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Plov de Samarcande',en:'Samarkand plov'},
  p:{fr:'Samarcande, Ouzbékistan',en:'Samarkand, Uzbekistan'},
  d:{fr:"Contrairement au plov de Tachkent, celui-ci ne se mélange jamais : riz, carottes et viande restent en couches distinctes jusqu'au service. Le riz devalzol de la vallée et la carotte jaune en font un plat de mariage.",
     en:"Unlike Tashkent plov, this one is never stirred: rice, carrots and meat stay in distinct layers until serving. Valley devzira rice and yellow carrot make it a wedding dish."},
  i:[['lamb_shoulder',1,'kg'],['lamb_fat',200,'g'],['long_grain_rice',800,'g'],['yellow_carrot',1,'kg'],['onion',400,'g'],['garlic',3,'pc'],['chickpeas',150,'g'],['cumin',2,'tbsp'],['barberries',3,'tbsp'],['quince',1,'pc'],['hot_pepper',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Rincez le riz jusqu'à l'eau claire et laissez-le tremper dans l'eau tiède salée pendant que le reste cuit.","Faites fondre le gras de mouton dans le kazan, retirez les grattons, et saisissez la viande en gros morceaux.","Ajoutez l'oignon en demi-lunes, puis la carotte jaune en bâtonnets épais — jamais râpée — et laissez-la fondre sans la brusquer.","Mouillez à hauteur, ajoutez les pois chiches trempés, les têtes d'ail entières, le coing et le cumin, et laissez mijoter 45 minutes : c'est le zirvak.","Étalez le riz égoutté par-dessus sans remuer, versez de l'eau bouillante à deux doigts, laissez évaporer à découvert puis couvrez 25 minutes. Servez en couches renversées."],
     en:["Rinse the rice until the water runs clear and soak it in warm salted water while the rest cooks.","Render the mutton fat in the kazan, remove the scratchings, and sear the meat in large pieces.","Add the onion in half-moons, then the yellow carrot in thick batons — never grated — and let it soften without hurrying it.","Cover with water, add the soaked chickpeas, whole garlic heads, quince and cumin, and simmer for 45 minutes: this is the zirvak.","Spread the drained rice on top without stirring, pour in boiling water to two fingers, let it evaporate uncovered then cover for 25 minutes. Serve in inverted layers."]} }
];
